import{_ as n,o as i,c as s,a2 as r}from"./chunks/framework.7R1OEGYz.js";const o="/docs/images/manual/login.png",l="/docs/images/manual/profil.png",h=JSON.parse('{"title":"2. Masuk, Keluar & Profil","description":"Cara login, lupa password, mengubah profil, dan logout.","frontmatter":{"title":"2. Masuk, Keluar & Profil","description":"Cara login, lupa password, mengubah profil, dan logout."},"headers":[],"relativePath":"akses.md","filePath":"akses.md"}'),t={name:"akses.md"};function e(u,a,d,g,p,m){return i(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="_2-masuk-keluar-profil" tabindex="-1">2. Masuk, Keluar &amp; Profil <a class="header-anchor" href="#_2-masuk-keluar-profil" aria-label="Permalink to &quot;2. Masuk, Keluar &amp; Profil&quot;">​</a></h1><p>Cara login, lupa password, mengubah profil, dan logout. <span class="manual-badge is-public">Akses: Semua Pengguna</span></p><h2 id="masuk-ke-aplikasi" tabindex="-1">Masuk ke aplikasi <a class="header-anchor" href="#masuk-ke-aplikasi" aria-label="Permalink to &quot;Masuk ke aplikasi&quot;">​</a></h2><ol><li>Buka alamat aplikasi di browser (Chrome, Edge, atau Firefox versi terbaru).</li><li>Isi <strong>Email atau NIP</strong> dan <strong>Password</strong> akun Anda.</li><li>Tekan <strong>Masuk</strong>. Anda akan diarahkan ke Dashboard.</li></ol><figure class="manual-figure"><p><img src="'+o+'" alt="Halaman login."></p><figcaption>Halaman login.</figcaption></figure><div class="warning custom-block"><p class="custom-block-title">Perhatian</p><p>Akun yang dinonaktifkan Administrator tidak dapat login (muncul pesan &quot;Akun Anda sedang nonaktif&quot;). Jika password selalu ditolak, hubungi Administrator.</p></div><p><strong>Lupa password:</strong> tekan tautan <strong>Lupa password?</strong> di halaman login. Aplikasi tidak mengirim email reset; hubungi Administrator untuk mengatur ulang password Anda.</p><h2 id="mengubah-nama-atau-password" tabindex="-1">Mengubah nama atau password <a class="header-anchor" href="#mengubah-nama-atau-password" aria-label="Permalink to &quot;Mengubah nama atau password&quot;">​</a></h2><ol><li>Tekan nama Anda di pojok kanan atas (di ponsel: ikon orang).</li><li>Pada kartu <strong>Data akun</strong>, ubah <strong>Nama</strong> lalu tekan <strong>Simpan profil</strong>.</li><li>Pada kartu <strong>Ganti password</strong>, isi password saat ini, password baru (minimal 8 karakter, harus berbeda), dan konfirmasinya, lalu tekan simpan.</li></ol><figure class="manual-figure"><p><img src="'+l+'" alt="Halaman Profil Saya: ubah nama dan ganti password."></p><figcaption>Halaman Profil Saya: ubah nama dan ganti password.</figcaption></figure><div class="info custom-block"><p class="custom-block-title">Catatan</p><p>Email, NIP, dan peran (role) hanya dapat diubah oleh Administrator.</p></div><h2 id="elemen-di-bagian-atas-layar-header" tabindex="-1">Elemen di bagian atas layar (header) <a class="header-anchor" href="#elemen-di-bagian-atas-layar-header" aria-label="Permalink to &quot;Elemen di bagian atas layar (header)&quot;">​</a></h2><ul><li><strong>Judul halaman</strong> yang sedang dibuka.</li><li><strong>Tanggal, jam WIT, dan shift berjalan</strong>: acuan waktu pengisian data.</li><li><strong>Ikon bulan / matahari</strong>: beralih mode gelap / terang (tersimpan di perangkat).</li><li><strong>Ikon ?</strong>: membuka panduan untuk halaman yang sedang dibuka.</li><li><strong>Ikon keluar</strong>: logout. Selalu logout jika memakai komputer bersama.</li></ul>',13)])])}const c=n(t,[["render",e]]);export{h as __pageData,c as default};
